// CalculateTax calculates the tax based on income using predefined brackets.
func CalculateTax(income float64) float64 {
	var tax float64

	if income <= 10000 {
		tax = income * 0.10
	} else if income <= 30000 {
		tax = (10000 * 0.10) + ((income - 10000) * 0.20)
	} else { // income > 30000
		tax = (10000 * 0.10) + (20000 * 0.20) + ((income - 30000) * 0.30)
	}
	return tax
}
